<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useAuth} from '../../entities/auth/model'
import {request,errorMessage,isCancelled} from '../../shared/api/client'
import type {Connection,Taxonomy,Taxon,Rubric,Member,Invitation,Organization} from '../../shared/interfaces'
import {datetime} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
import Notice from '../../shared/ui/Notice.vue'
import Empty from '../../shared/ui/Empty.vue'
import SheetMapping from '../../features/sheet-mapping/SheetMapping.vue'
import {defaultSheetMapping,validateSheetMapping} from '../../shared/lib/sheet-mapping'
const auth=useAuth(),route=useRoute(),tab=computed(()=>String(route.params.tab||'organization')),busy=ref(false),loading=ref(false),error=ref(''),success=ref(''),connections=ref<Connection[]>([]),taxonomy=ref<Taxonomy>({tags:[],statuses:[]}),rubrics=ref<Rubric[]>([]),members=ref<Member[]>([]),invitations=ref<Invitation[]>([])
const organization=ref<Partial<Organization>>({}),allowInbound=ref(true),minDuration=ref(5),workStart=ref('09:00'),workEnd=ref('18:00'),workdays=ref<number[]>([1,2,3,4,5]),workEnabled=ref(false)
const memberEmail=ref(''),memberRole=ref('manager'),taxonKind=ref('tag'),taxonName=ref(''),taxonColor=ref('#3f967d'),editingTaxon=ref<Taxon|null>(null)
const rubricName=ref('Оценка качества диалога'),criteria=ref<Rubric['criteria']>([])
const config=ref<Record<string,unknown>>({}),mapping=ref<Record<string,string>>({}),extensionMapping=ref(''),syncFrom=ref(''),syncTo=ref(''),allHistory=ref(false)
const menu=[['organization','Компания и правила'],['members','Сотрудники и доступ'],['taxonomy','Теги и статусы'],['rubrics','Критерии качества'],['telphin','Телфин'],['asr','Расшифровка'],['analysis','Нейросетевой анализ'],['amocrm','amoCRM'],['sheets','Google Таблицы']]
const isConnection=computed(()=>['telphin','asr','analysis','amocrm','sheets'].includes(tab.value))
const selectedConnection=computed(()=>connections.value.find(c=>c.kind===tab.value))
const titles:Record<string,[string,string]>={organization:['Компания и правила обработки','Часовой пояс, время перезвона и хранение данных.'],members:['Сотрудники и доступ','Приглашайте коллег и сопоставляйте добавочные номера.'],taxonomy:['Теги и бизнес-статусы','Единая разметка для команды и автоматического анализа.'],rubrics:['Критерии качества','Версионированная шкала оценки ваших разговоров.'],telphin:['Подключение Телфина','Импорт истории АТС и записей разговоров.'],asr:['Расшифровка разговоров','Провайдер распознавания речи и разделения участников.'],analysis:['Нейросетевой анализ','Модель для оценки диалога, резюме и разметки.'],amocrm:['Подключение amoCRM','Связывайте разговоры с контактами и сделками.'],sheets:['Google Таблицы','Обновляйте выбранную таблицу результатами звонков.']}
const title=computed(()=>titles[tab.value]||titles.organization!)
const asrModels=[{id:'moondream/parakeet-ultra',name:'Moondream · Parakeet Ultra'},{id:'nvidia/nemotron-3.5-transcribe',name:'NVIDIA · Nemotron 3.5 Transcribe'}]
const isOpenCodeAsr=computed(()=>tab.value==='asr'&&config.value.provider==='opencode')
function changeProvider(){if(tab.value!=='asr')return;config.value.api_key='';if(config.value.provider==='opencode'){config.value.model=asrModels.some(m=>m.id===config.value.model)?config.value.model:asrModels[0]!.id;config.value.base_url=selectedConnection.value?.config.provider==='opencode'?selectedConnection.value.config.base_url||'http://model-runner:4096':'http://model-runner:4096'}else if(asrModels.some(m=>m.id===config.value.model)||config.value.base_url==='http://model-runner:4096'){config.value.model='';config.value.base_url=config.value.provider==='openai'?'https://api.openai.com/v1':''}}
const fields=computed(()=>{
 const common=[{key:'provider',label:'Провайдер',type:'provider'},{key:'model',label:'Модель',type:'text'},{key:'base_url',label:'Адрес API / сервера',type:'url'},{key:'api_key',label:'API-ключ',type:'password'}]
 const map:Record<string,{key:string;label:string;type:string}[]>={telphin:[{key:'host',label:'Сервер API',type:'text'},{key:'client_id',label:'ID клиента АТС · необязательно',type:'text'},{key:'app_id',label:'App ID доверенного приложения',type:'text'},{key:'app_secret',label:'App Secret',type:'password'},{key:'history_start',label:'Начало доступной истории',type:'date'}],asr:common,analysis:[...common,{key:'budget_daily',label:'Дневной бюджет провайдера',type:'number'},{key:'timeout_seconds',label:'Таймаут обработки, секунд',type:'number'}],amocrm:[{key:'account_domain',label:'Домен аккаунта amoCRM',type:'text'},{key:'client_id',label:'ID интеграции',type:'text'},{key:'client_secret',label:'Секрет интеграции',type:'password'},{key:'redirect_uri',label:'Адрес возврата OAuth',type:'url'}],sheets:[{key:'client_id',label:'OAuth Client ID',type:'text'},{key:'client_secret',label:'OAuth Client Secret',type:'password'},{key:'redirect_uri',label:'Адрес возврата OAuth',type:'url'},{key:'spreadsheet_id',label:'ID Google Таблицы',type:'text'},{key:'sheet_name',label:'Название листа',type:'text'}]}
 return (map[tab.value]||[]).map(field=>isOpenCodeAsr.value&&field.key==='model'?{...field,type:'asr-model'}:isOpenCodeAsr.value&&field.key==='api_key'?{...field,label:'API-ключ OpenRouter'}:field)
})
function configure(){const existing=selectedConnection.value?.config||{};config.value={...existing};for(const key of ['app_secret','api_key','client_secret','access_token','refresh_token'])config.value[key]='';if(tab.value==='telphin'){if(!config.value.host)config.value.host='apiproxy.telphin.ru';config.value.history_start_verified=existing.history_start_verified===true;config.value.history_start=typeof existing.history_start==='string'?existing.history_start.slice(0,10):'';extensionMapping.value=JSON.stringify(existing.extension_mapping||{},null,2);}if(['asr','analysis'].includes(tab.value)&&!config.value.provider)config.value.provider='openai';mapping.value={...((existing.column_mapping as Record<string,string>|undefined)||defaultSheetMapping)}}
async function load(){error.value='';success.value='';loading.value=true;try{organization.value={...auth.me?.organization};const org=auth.me?.organization;allowInbound.value=org?.callback_allow_inbound!==false;minDuration.value=org?.callback_min_duration??5;const working=org?.working_hours as {enabled?:boolean;days?:number[];start?:string;end?:string}|undefined;workEnabled.value=!!working?.enabled;workdays.value=working?.days||[1,2,3,4,5];workStart.value=working?.start||'09:00';workEnd.value=working?.end||'18:00';if(tab.value==='members'){const result=await request<{items:Member[];invitations:Invitation[]}>('/members');members.value=result.items;invitations.value=result.invitations}if(tab.value==='taxonomy')taxonomy.value=await request<Taxonomy>('/taxonomy');if(tab.value==='rubrics'){rubrics.value=(await request<{items:Rubric[]}>('/rubrics')).items;const active=rubrics.value.find(r=>r.active)||rubrics.value[0];if(active){rubricName.value=active.name;criteria.value=active.criteria.map(c=>({...c}))}else criteria.value=[]}if(isConnection.value){connections.value=(await request<{items:Connection[]}>('/connections')).items;configure()}}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{loading.value=false}}
async function action(task:()=>Promise<unknown>,message:string){error.value='';success.value='';busy.value=true;try{await task();success.value=message;return true}catch(e){if(!isCancelled(e))error.value=errorMessage(e);return false}finally{busy.value=false}}
async function saveOrganization(){if(await action(async()=>{await request('/organization',{method:'PATCH',body:{...organization.value,callback_allow_inbound:allowInbound.value,callback_min_duration:minDuration.value,working_hours:workEnabled.value?{enabled:true,days:workdays.value,start:workStart.value,end:workEnd.value}:null}});await auth.load()},'Настройки компании сохранены'))organization.value={...auth.me?.organization}}
async function invite(){if(await action(()=>request('/members/invite',{method:'POST',body:{email:memberEmail.value,role:memberRole.value}}),'Приглашение отправлено на почту')){memberEmail.value='';const r=await request<{items:Member[];invitations:Invitation[]}>('/members');members.value=r.items;invitations.value=r.invitations}}
async function saveMember(member:Member){await action(()=>request('/members/'+member.id,{method:'PATCH',body:{role:member.role,extension:member.extension}}),'Доступ сотрудника обновлён')}
async function revokeMember(member:Member){if(await action(()=>request('/members/'+member.id,{method:'DELETE'}),'Доступ отозван'))members.value=members.value.filter(m=>m.id!==member.id)}
async function revokeInvite(id:string){if(await action(()=>request('/members/invitations/'+id,{method:'DELETE'}),'Приглашение отозвано'))invitations.value=invitations.value.map(i=>i.id===id?{...i,revoked:true}:i)}
async function createTaxon(){if(!taxonName.value.trim())return;if(await action(()=>request('/taxonomy'+(editingTaxon.value?'/'+editingTaxon.value.id:''),{method:editingTaxon.value?'PATCH':'POST',body:{...(!editingTaxon.value?{kind:taxonKind.value}:{}),name:taxonName.value,color:taxonColor.value}}),'Разметка сохранена')){editingTaxon.value=null;taxonName.value='';taxonomy.value=await request<Taxonomy>('/taxonomy')}}
function editTaxon(item:Taxon){editingTaxon.value=item;taxonName.value=item.name;taxonColor.value=item.color}
async function archive(item:Taxon){if(await action(()=>request('/taxonomy/'+item.id,{method:'PATCH',body:{archived:!item.archived}}),item.archived?'Метка восстановлена':'Метка архивирована'))taxonomy.value=await request<Taxonomy>('/taxonomy')}
function addCriterion(){criteria.value.push({id:crypto.randomUUID(),name:'',weight:1,required:true,instruction:'',evaluation_mode:'checklist'})}
function addExamples(){for(const[name,instruction]of [['Приветствие','Сотрудник поздоровался, представился и назвал компанию. Приведи точную цитату.'],['Корпоративный стандарт','Опиши здесь свой стандарт: какую фразу или действие должен выполнить сотрудник.'],['Приглашение на семинар','Сотрудник пригласил клиента на семинар и объяснил, как записаться.']])criteria.value.push({id:crypto.randomUUID(),name:name!,instruction:instruction!,weight:1,required:true,evaluation_mode:'checklist'})}
async function createRubric(){if(await action(async()=>{if(!criteria.value.length||criteria.value.some(c=>!c.name.trim()||c.weight<=0))throw Error('Добавьте критерии с названием и положительным весом');const r=await request<Rubric>('/rubrics',{method:'POST',body:{name:rubricName.value,criteria:criteria.value}});await request('/rubrics/'+r.id+'/activate',{method:'POST',body:{}})},'Новая версия критериев сохранена и активирована'))rubrics.value=(await request<{items:Rubric[]}>('/rubrics')).items}
async function activate(id:string){if(await action(()=>request('/rubrics/'+id+'/activate',{method:'POST',body:{}}),'Версия активирована'))rubrics.value=(await request<{items:Rubric[]}>('/rubrics')).items}
async function saveConnection(){if(!auth.isOwner||busy.value)return;await action(async()=>{const body={...config.value};if(tab.value==='asr'&&body.provider!=='demo'&&body.provider!==selectedConnection.value?.config.provider&&!(typeof body.api_key==='string'&&body.api_key.trim()&&body.api_key!=='<configured>'))throw Error('При смене провайдера укажи новый API-ключ: ключ предыдущего провайдера не переносится');if(isOpenCodeAsr.value&&!asrModels.some(m=>m.id===body.model))throw Error('Выбери поддерживаемую модель расшифровки');for(const key of ['budget_daily','timeout_seconds'])if(body[key]!==undefined&&body[key]!=='')body[key]=Number(body[key]);if(tab.value==='telphin'){let parsed:unknown;try{parsed=extensionMapping.value.trim()?JSON.parse(extensionMapping.value):{}}catch{throw Error('Проверьте JSON сопоставления номеров. Например, {"12345":"101"}')} if(!parsed||typeof parsed!=='object'||Array.isArray(parsed)||Object.entries(parsed).some(([key,value])=>!key.trim()||typeof value!=='string'||!value.trim()))throw Error('Сопоставление номеров должно быть JSON-объектом: ID Телфина и непустой добавочный строкой. Например, {"12345":"101"}');body.extension_mapping=parsed;}if(tab.value==='sheets')body.column_mapping=validateSheetMapping(mapping.value);await request('/connections/'+tab.value,{method:'PUT',body:{config:body}});connections.value=(await request<{items:Connection[]}>('/connections')).items;configure()},'Подключение сохранено. Проверьте соединение перед запуском обработки.')}
async function testConnection(){await action(async()=>{const r=await request<{ok:boolean;message:string}>('/connections/'+tab.value+'/test',{method:'POST',body:{}});if(!r.ok)throw Error(r.message||'Проверка подключения не пройдена');success.value=r.message||'Соединение проверено'},'Проверка соединения завершена')}
async function disconnect(){if(await action(()=>request('/connections/'+tab.value,{method:'DELETE'}),'Подключение отключено')){connections.value=(await request<{items:Connection[]}>('/connections')).items;configure()}}
async function sync(){await action(()=>request('/connections/telphin/sync',{method:'POST',body:{...(allHistory.value?{all_available:true}:{from:syncFrom.value||undefined,to:syncTo.value||undefined})}}),'Импорт поставлен в очередь. Состояние доступно в разделе «Обработка и аудит».')}
async function authorize(){await action(async()=>{const r=await request<{url:string}>('/integrations/'+tab.value+'/authorize');const url=new URL(r.url);if(url.protocol!=='https:')throw Error('Сервер вернул небезопасный адрес авторизации');window.location.assign(url.href)},'Открываем страницу авторизации')}
watch(tab,load);onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">Рабочее пространство вашей команды</span><h1>Настройки</h1><p>Управляйте доступом, источниками данных и правилами оценки.</p></div><span class="badge outline">{{auth.me?.organization.name}}</span></div><div class="settings-layout"><nav class="settings-nav" aria-label="Разделы настроек"><RouterLink v-for="[value,label] in menu" :key="value" :to="'/settings/'+value" :class="{active:tab===value}">{{label}}</RouterLink></nav><div><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><Notice v-if="!auth.isOwner" message="Настройки доступны для просмотра. Изменять их может только владелец компании."/><div class="card"><div class="card-header"><div><h3>{{title[0]}}</h3><p>{{title[1]}}</p></div><Icon name="settings" :size="17" style="color:#a8bbb5"/></div><Empty v-if="loading" loading/>
<form v-else-if="tab==='organization'" class="card-body" @submit.prevent="saveOrganization"><div class="form-grid"><label class="wide">Название компании<input v-model="organization.name" :disabled="!auth.isOwner" required/></label><label>Часовой пояс<select v-model="organization.timezone" :disabled="!auth.isOwner"><option>Europe/Moscow</option><option>Europe/Kaliningrad</option><option>Asia/Yekaterinburg</option><option>Asia/Novosibirsk</option><option>Asia/Irkutsk</option><option>Asia/Vladivostok</option><option>UTC</option></select></label><label>Срок перезвона, минут<input v-model.number="organization.callback_minutes" type="number" min="1" max="10080" :disabled="!auth.isOwner" required/></label><label>Минимальная длительность разговора, сек<input v-model.number="minDuration" type="number" min="0" max="3600" :disabled="!auth.isOwner"/></label><label>Срок хранения данных, дней<input v-model.number="organization.retention_days" type="number" min="1" max="3650" :disabled="!auth.isOwner"/></label><label class="checkbox wide"><input v-model="allowInbound" type="checkbox" :disabled="!auth.isOwner"/>Успешный повторный входящий закрывает пропущенное обращение</label><label class="checkbox wide"><input v-model="workEnabled" type="checkbox" :disabled="!auth.isOwner"/>Считать срок обработки по рабочим часам</label><template v-if="workEnabled"><div class="inline-labels wide"><label v-for="([num,label]) in [[1,'Пн'],[2,'Вт'],[3,'Ср'],[4,'Чт'],[5,'Пт'],[6,'Сб'],[7,'Вс']]" :key="num" class="checkbox" style="margin-right:9px"><input v-model="workdays" type="checkbox" :value="num" :disabled="!auth.isOwner"/>{{label}}</label></div><label>Начало рабочего дня<input v-model="workStart" type="time" :disabled="!auth.isOwner"/></label><label>Конец рабочего дня<input v-model="workEnd" type="time" :disabled="!auth.isOwner"/></label></template></div><p class="token-hint">Разговор с сотрудником подтверждается соединением. Ответ IVR и попытка дозвона без ответа не закрывают обращение.</p><div v-if="auth.isOwner" class="form-actions"><button class="button primary" :disabled="busy">Сохранить настройки</button></div></form>
<div v-else-if="tab==='members'" class="card-body"><form v-if="auth.isOwner" class="form-inline" @submit.prevent="invite"><label>Пригласить по рабочей почте<input v-model="memberEmail" type="email" placeholder="colleague@company.ru" required/></label><label>Роль<select v-model="memberRole"><option value="manager">Менеджер</option><option value="reviewer">Наблюдатель</option><option value="owner">Владелец</option></select></label><button class="button primary" :disabled="busy">Пригласить</button></form><div class="divider"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Участник</th><th>Роль</th><th>Добавочный Телфина</th><th></th></tr></thead><tbody><tr v-for="member in members" :key="member.id"><td class="primary-text">{{member.name||member.email}}<small>{{member.email}}</small></td><td><select v-model="member.role" :disabled="!auth.isOwner"><option value="owner">Владелец</option><option value="manager">Менеджер</option><option value="reviewer">Наблюдатель</option></select></td><td><input v-model="member.extension" placeholder="101" style="max-width:110px" :disabled="!auth.isOwner"/></td><td><div v-if="auth.isOwner" class="row-actions"><button class="button small" :disabled="busy" @click="saveMember(member)">Сохранить</button><button class="icon-button" aria-label="Отозвать доступ" :disabled="busy||member.id===auth.me?.user.id" @click="revokeMember(member)"><Icon name="close" :size="14"/></button></div></td></tr></tbody></table></div><template v-if="invitations.length"><div class="divider"></div><h4>Приглашения</h4><ul class="list-clean"><li v-for="invite in invitations" :key="invite.id" style="display:flex;justify-content:space-between;gap:15px"><span>{{invite.email}}<small class="subtle"> · {{invite.revoked?'Отозвано':'Действует до '+datetime(invite.expires_at)}}</small></span><button v-if="auth.isOwner&&!invite.revoked" class="text-link" :disabled="busy" @click="revokeInvite(invite.id)">Отозвать</button></li></ul></template><p class="token-hint">Менеджер работает со звонками и разметкой. Наблюдатель только просматривает данные. Владелец управляет настройками и доступом.</p></div>
<div v-else-if="tab==='taxonomy'" class="card-body"><form v-if="auth.isOwner" class="form-inline" @submit.prevent="createTaxon"><label>Тип<select v-model="taxonKind" :disabled="!!editingTaxon"><option value="tag">Тег</option><option value="status">Бизнес-статус</option></select></label><label>Название<input v-model="taxonName" required placeholder="Например, интерес к услуге"/></label><label style="flex:0;min-width:60px">Цвет<input v-model="taxonColor" type="color" style="width:55px;height:39px;padding:4px"/></label><button class="button primary" :disabled="busy">{{editingTaxon?'Сохранить':'Добавить'}}</button><button v-if="editingTaxon" type="button" class="button" @click="editingTaxon=null;taxonName=''">Отмена</button></form><div class="grid-even" style="margin-top:25px"><div v-for="[group,label] in [['tags','Теги'],['statuses','Бизнес-статусы']]" :key="group"><h4>{{label}}</h4><ul class="list-clean"><li v-for="item in taxonomy[group as 'tags'|'statuses']" :key="item.id" style="display:flex;align-items:center;justify-content:space-between;gap:10px"><span class="badge outline" :style="{color:item.color,opacity:item.archived?.5:1}">{{item.name}}{{item.archived?' · архив':''}}</span><div v-if="auth.isOwner" class="row-actions"><button class="text-link" @click="editTaxon(item)">Изменить</button><button class="subtle" @click="archive(item)">{{item.archived?'Вернуть':'В архив'}}</button></div></li></ul><p v-if="!taxonomy[group as 'tags'|'statuses'].length" class="subtle">Пока не добавлены</p></div></div><p class="token-hint">Архивные метки сохраняются в истории, но не назначаются автоматически новым звонкам.</p></div>
<div v-else-if="tab==='rubrics'" class="card-body"><Notice message="Изменения создают новую версию шкалы. Результаты прошлых анализов сохраняют свои критерии."/><p class="token-hint">Запись → расшифровка → проверка каждого требования. Для «Да / Нет» модель укажет выполнение и цитату; при недостатке данных ответ останется неопределённым. Примеры можно изменить под свои стандарты.</p><form v-if="auth.isOwner" @submit.prevent="createRubric"><label>Название шкалы<input v-model="rubricName" required/></label><div style="margin-top:20px"><div v-for="(criterion,i) in criteria" :key="criterion.id" class="rubric-criterion"><label>Название критерия<input v-model="criterion.name" required placeholder="Выявление потребности"/></label><label>Способ оценки<select v-model="criterion.evaluation_mode" aria-label="Способ оценки" :disabled="!auth.isOwner"><option :value="undefined">Баллы 0–5 (ранее заданный)</option><option value="score">Баллы 0–5</option><option value="checklist">Выполнено: Да / Нет</option></select></label><label>Вес<input v-model.number="criterion.weight" type="number" min="0.1" step="0.1" required/></label><button type="button" class="icon-button" aria-label="Удалить критерий" @click="criteria.splice(i,1)"><Icon name="close" :size="14"/></button><textarea v-model="criterion.instruction" :aria-label="'Инструкция: '+criterion.name" placeholder="Как оценивать этот критерий и какие доказательства нужны"></textarea><label class="checkbox" style="grid-column:1/-1"><input v-model="criterion.required" type="checkbox"/>Обязателен для итоговой оценки</label></div></div><div class="form-actions" style="justify-content:space-between"><button type="button" class="button" @click="addExamples">Добавить примеры</button><button type="button" class="button" @click="addCriterion"><Icon name="plus" :size="14"/>Добавить критерий</button><button class="button primary" :disabled="busy">Сохранить новую версию</button></div></form><div class="divider"></div><h4>Версии шкалы</h4><ul class="list-clean"><li v-for="rubric in rubrics" :key="rubric.id" style="display:flex;align-items:center;justify-content:space-between;gap:10px"><span>{{rubric.name}} · v{{rubric.rubric_version??rubric.version}}<small class="subtle"> · {{rubric.criteria.length}} критериев</small></span><span v-if="rubric.active" class="badge teal">Активна</span><button v-else-if="auth.isOwner" class="text-link" @click="activate(rubric.id)">Активировать</button></li></ul><Empty v-if="!rubrics.length" title="Шкала ещё не задана" description="Добавьте критерии, по которым модель будет оценивать разговор."/></div>
<div v-else-if="isConnection" class="card-body"><div class="section-title"><span class="badge" :class="selectedConnection?.state==='configured'?'teal':selectedConnection?.state==='error'?'red':'outline'">{{selectedConnection?.state==='configured'?'Настроено':selectedConnection?.state==='error'?'Ошибка подключения':'Не подключено'}}</span><span v-if="selectedConnection?.last_sync_at" class="subtle">Последняя синхронизация: {{datetime(selectedConnection.last_sync_at)}}</span></div><Notice v-if="['asr','analysis'].includes(tab)&&config.provider==='demo'" message="Сейчас выбран демонстрационный провайдер. Реальные записи он не обрабатывает: выбери рабочего провайдера, укажи модель и доступы."/><Notice v-if="isOpenCodeAsr" message="OpenCode Docker-коннектор отправляет запись в выбранную модель через ASR-адаптер. Туннель и компьютер должны быть включены. OpenRouter оплачивается отдельно; вход в Codex не подключает этот API."/><Notice v-if="tab==='asr'" message="Сначала запись превращается в текст, затем текст передаётся на оценку. Вход в Codex помощника не подключает распознавание речи автоматически."/><Notice v-if="selectedConnection?.last_error" :message="selectedConnection.last_error" kind="error"/><form @submit.prevent="saveConnection"><div class="form-grid"><label v-for="field in fields" :key="field.key">{{field.label}}<select :aria-label="field.label" v-if="field.type==='provider'" v-model="config[field.key]" :disabled="!auth.isOwner" @change="changeProvider"><option value="openai">OpenAI API</option><option value="opencode">{{tab==='asr'?'OpenCode (Docker) → OpenRouter':'OpenCode runner'}}</option><option value="http">Совместимый HTTP API</option><option v-if="auth.me?.demo_mode" value="demo">Демонстрационный провайдер</option></select><select :aria-label="field.label" v-else-if="field.type==='asr-model'" v-model="config[field.key]" :disabled="!auth.isOwner" required><option v-if="!asrModels.some(m=>m.id===config.model)" :value="config.model" disabled>Выбери поддерживаемую модель</option><option v-for="model in asrModels" :key="model.id" :value="model.id">{{model.name}}</option></select><input :aria-label="field.label" v-else v-model="config[field.key]" :type="field.type" :disabled="!auth.isOwner" :readonly="isOpenCodeAsr&&field.key==='base_url'" :autocomplete="field.type==='password'?'new-password':'off'" :required="field.key==='history_start'&&config.history_start_verified===true" :placeholder="field.type==='password'&&selectedConnection?'Оставьте пустым, чтобы сохранить':field.key==='base_url'&&tab==='analysis'&&config.provider==='opencode'?'http://model-runner:4096':''" :min="field.type==='number'?0:undefined"/></label><label v-if="tab==='telphin'" class="wide">Сопоставление ID внутренних номеров Телфина с добавочными<textarea v-model="extensionMapping" class="token-input" :disabled="!auth.isOwner" rows="5" placeholder='{"12345":"101"}'></textarea><span class="token-hint">Необязательно. Сверьте ID внутренних номеров в АТС; тот же добавочный укажите в разделе «Сотрудники и доступ». Пустое поле означает отсутствие сопоставлений.</span></label><label v-if="tab==='telphin'" class="checkbox wide"><input v-model="config.history_start_verified" type="checkbox" :disabled="!auth.isOwner"/>Граница истории сверена с АТС</label></div><template v-if="tab==='sheets'"><SheetMapping v-model="mapping" :disabled="!auth.isOwner"/><p class="token-hint">Одна таблица и один лист на компанию. Укажи любой доступный Google-аккаунту документ. Для нескольких таблиц выгрузи звонки в отдельный лист, затем подтяни нужные поля формулами IMPORTRANGE или Apps Script. Прямой записи в произвольные ячейки сделок здесь нет.</p></template><p v-if="tab==='telphin'" class="token-hint">Достаточно App ID и App Secret: ID клиента АТС определится автоматически.</p><p class="token-hint">Ключи доступны только серверу. Сохранённые секреты не возвращаются в браузер. Проверка соединения показывает фактический результат провайдера.</p><div v-if="auth.isOwner" class="form-actions"><button v-if="selectedConnection&&selectedConnection.state!=='disconnected'" class="button danger" type="button" :disabled="busy" @click="disconnect">Отключить</button><button class="button" type="button" :disabled="busy||!selectedConnection" @click="testConnection">Проверить соединение</button><button class="button primary" :disabled="busy">Сохранить</button></div></form><template v-if="['amocrm','sheets'].includes(tab)&&auth.isOwner"><div class="divider"></div><h4>Разрешить доступ через OAuth</h4><p class="subtle">После сохранения параметров откройте страницу провайдера и подтвердите доступ к вашему аккаунту.</p><button class="button" :disabled="busy||!selectedConnection" @click="authorize">Авторизовать {{tab==='amocrm'?'amoCRM':'Google'}}</button></template><template v-if="tab==='telphin'&&auth.isOwner"><div class="divider"></div><h4>Загрузить историю звонков</h4><form @submit.prevent="sync"><div class="form-grid"><label>С даты<input v-model="syncFrom" type="date" :disabled="allHistory"/></label><label>По дату<input v-model="syncTo" type="date" :disabled="allHistory"/></label><label class="checkbox wide"><input v-model="allHistory" type="checkbox"/>Запросить всю доступную историю</label></div><p class="token-hint">Пропущенные звонки и вызовы без записи также загружаются. Без подтверждённой границы истории запрос «вся доступная история» проверяет последний год; полнота остаётся неподтверждённой. С подтверждённой границей импорт идёт назад до указанной даты начала истории. Сохраните параметры подключения перед импортом.</p><div class="form-actions"><button class="button primary" :disabled="busy||selectedConnection?.state!=='configured'">Запустить импорт</button></div></form></template></div>
</div></div></div></template>

<style scoped>.rubric-criterion{grid-template-columns:minmax(140px,1.5fr) minmax(120px,1fr) 72px 30px}.rubric-criterion textarea{grid-column:1/-1}@media(max-width:760px){.rubric-criterion{grid-template-columns:minmax(0,1fr) 72px}.rubric-criterion>label:first-child{grid-column:1/-1}}</style>
